        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }

    /* i 是读指针，k 是写指针，a[0..k-1] 为已去重区间 */
    for (i = 1; i < n; i++) {
        if (a[i] != a[k - 1]) {
            a[k] = a[i];
            k++;
        }
    }

    printf("%d\n", k);
    for (i = 0; i < k; i++) {
        if (i > 0)
            putchar(' ');
        printf("%d", a[i]);
    }
    putchar('\n');
    return 0;
}

