/* 通过指针交换调用方的两个变量 */
void swap(int *p, int *q)
{
    int t = *p;
    *p = *q;
    *q = t;
}

/* 选择排序：用指针扫描未排序区间，找最小元素的地址并交换 */
void sort_asc(int *begin, int *end)
{
    int *i, *j, *minp;

    for (i = begin; i < end - 1; i++) {
        minp = i;
        for (j = i + 1; j < end; j++)
            if (*j < *minp)
                minp = j;
        if (minp != i)
            swap(i, minp);
    }
}

