#define MAXN 1000

/* 比较器：绝对值从大到小，绝对值相同则数值从小到大 */
static int cmp_abs_desc(const void *pa, const void *pb)
{
    int a = *(const int *)pa;
    int b = *(const int *)pb;
    int aa = a < 0 ? -a : a;
    int ab = b < 0 ? -b : b;

    if (aa != ab)
        return ab - aa;     /* 绝对值大的排前面 */
    if (a < b)
        return -1;
    if (a > b)
        return 1;
    return 0;
}

int main(void)
{
    int n, i;
    int a[MAXN];

    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }

    qsort(a, (size_t)n, sizeof(a[0]), cmp_abs_desc);

    for (i = 0; i < n; i++) {
        if (i > 0)
            putchar(' ');
        printf("%d", a[i]);
    }
    putchar('\n');
