    if (cnt == 0) {
        free(a);
        return 0;
    }

    maxv = a[0];
    for (i = 0; i < cnt; i++) {
        sum += a[i];
        if (a[i] > maxv)
            maxv = a[i];
    }

    printf("count=%d\n", cnt);
    printf("sum=%lld\n", sum);
    printf("max=%d\n", maxv);
    free(a);
    return 0;
