#include <stdio.h>
#include <string.h>

#define MAXLEN 210

static void reverse_range(char *left, char *right)
{
    while (left < right) {
        char t = *left;
        *left = *right;
        *right = t;
        left++;
        right--;
    }
}

int main(void)
{
    char s[MAXLEN];
    size_t len;
    char *p, *q;

    if (fgets(s, sizeof(s), stdin) == NULL)
        return 0;

    len = strlen(s);
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r'))
        s[--len] = '\0';
    if (len == 0)
        return 0;

    /* 第一次反转：整个字符串倒序 */
    reverse_range(s, s + len - 1);

    /* 第二次反转：每个单词内部再倒序回来 */
    p = s;
    while (*p != '\0') {
        while (*p == ' ')
            p++;
        if (*p == '\0')
            break;
        q = p;
        while (*q != '\0' && *q != ' ')
            q++;
        reverse_range(p, q - 1);
        p = q;
    }

    printf("%s\n", s);
    return 0;
}

