/* 反转 [begin, end) 区间，end 为尾后指针 */
static void reverse_range(int *begin, int *end)
{
    int *left = begin;
    int *right;

    if (begin == end)
        return;
    right = end - 1;

    while (left < right) {
        int t = *left;
        *left = *right;
        *right = t;
        left++;
        right--;
    }
}

int main(void)
{
    int n, k, i;
    int a[MAXN];

    if (scanf("%d %d", &n, &k) != 2 || n < 1 || n > MAXN || k < 0)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }

    k %= n;
    reverse_range(a, a + k);        /* 反转前 k 个 */
    reverse_range(a + k, a + n);    /* 反转后 n-k 个 */
    reverse_range(a, a + n);        /* 整体反转 */

    for (i = 0; i < n; i++) {
        if (i > 0)
            putchar(' ');
        printf("%d", a[i]);
