#define MAXN 1000

/* 挖坑法划分：返回基准的最终下标 */
static int partition(int *a, int n)
{
    int pivot = a[0];
    int i = 0;
    int j = n - 1;

    while (i < j) {
        while (i < j && a[j] >= pivot)
            j--;
        a[i] = a[j];                /* 右端小于 pivot 的元素填左坑 */
        while (i < j && a[i] < pivot)
            i++;
        a[j] = a[i];                /* 左端大于等于 pivot 的元素填右坑 */
    }
    a[i] = pivot;
    return i;
}

int main(void)
{
    int n, i, idx;
    int a[MAXN];

    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1)
            return 0;
    }

    idx = partition(a, n);
    printf("pivot_index=%d\n", idx);
