#include <iostream>
#include <vector>

int partition(int *a, int n)
{
    int pivot = a[0];
    int *p = a;
    int *q = a + n - 1;

    while (p < q) {
        while (p < q && *q >= pivot)
            --q;
        *p = *q;
        while (p < q && *p < pivot)
            ++p;
        *q = *p;
    }
    *p = pivot;
    return static_cast<int>(p - a);
}

int main()
{
    int n;
    if (!(std::cin >> n) || n < 1 || n > 1000)
        return 0;

    std::vector<int> a(n);
    for (int i = 0; i < n; ++i)
        std::cin >> a[i];

    int idx = partition(a.data(), n);
    std::cout << "pivot_index=" << idx << '\n';
    for (int i = 0; i < n; ++i) {
        if (i > 0)
            std::cout << ' ';
        std::cout << a[i];
    }
    std::cout << '\n';
    return 0;
}

