#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXN 50
#define MAXLEN 20

/* qsort 比较器：pa、pb 指向 char * 元素，解引用后得到字符串首地址 */
static int cmp_str(const void *pa, const void *pb)
{
    const char *const *x = (const char *const *)pa;
    const char *const *y = (const char *const *)pb;

    return strcmp(*x, *y);
}

int main(void)
{
    int n, i;
    char buf[MAXN][MAXLEN];
    char *p[MAXN];

    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN)
        return 0;
    for (i = 0; i < n; i++) {
        if (scanf("%19s", buf[i]) != 1)
            return 0;
        p[i] = buf[i];              /* 指针指向对应的字符串 */
    }

    qsort(p, (size_t)n, sizeof(p[0]), cmp_str);

    for (i = 0; i < n; i++)
        printf("%s\n", p[i]);
    return 0;
}

